#!/usr/bin/env node
// Live DAP verification for the built-in gdb adapter.
//
// Gate 1 is the preflight: gdb must be DAP-capable (Python + dap
// interpreter). On a host without it the script exits non-zero here, which is
// what CI asserts on such hosts (see scripts/verify-dap.expected.md).
//
// Past the gate, the script exercises real DAP behavior through
// verify-dap-client.mjs: a launch with the printers `-iex` mechanism, a
// core-file attach, and a live-PID attach (the `pid` field the provider maps
// `processId` to). The core file is generated by gdb itself so no kernel
// core_pattern configuration is needed.
//
// Runs on Windows, macOS and Linux: Node stdlib only (no shell, no grep,
// no timeout binary, no mktemp).
import { spawn, spawnSync } from "node:child_process"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

const scriptsDir = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(scriptsDir, "..")

function flagValue(name) {
	const prefix = `--${name}=`
	const found = process.argv.slice(2).find((token) => token.startsWith(prefix))
	return found ? found.slice(prefix.length) : undefined
}

const GDB = flagValue("gdb") ?? process.env.GDB ?? "gdb"
const CC = flagValue("cc") ?? process.env.CC ?? "cc"
const EXE = process.platform === "win32" ? ".exe" : ""

/** Whether a command resolves: spawning it does not fail outright. */
function commandExists(command) {
	const result = spawnSync(command, ["--version"], { stdio: "ignore" })
	return !result.error
}

/** Run gdb and return combined stdout + stderr (failures collapse to text). */
function gdbOutput(args, options = {}) {
	try {
		const result = spawnSync(GDB, args, {
			encoding: "utf8",
			stdio: ["ignore", "pipe", "pipe"],
			...options,
		})
		return `${result.stdout ?? ""}\n${result.stderr ?? ""}`
	} catch {
		return ""
	}
}

/** First `X.Y` on the `--version` banner's first line. */
function gdbVersion() {
	const firstLine = gdbOutput(["--version"]).split(/\r?\n/)[0] ?? ""
	return firstLine.match(/\d+\.\d+/)?.[0] ?? ""
}

/** The preflight no-DAP error, naming the probed version like the extension does. */
function noDapSupport() {
	const ver = gdbVersion()
	return `gdb ${ver} has no DAP support (built without Python). Install gdb >= 13 with Python, or enable the cppdbg fallback (v.debug.adapter = 'cppdbg').`
}

class VerifyFailure extends Error {}

function failLine(line) {
	console.log(line)
	throw new VerifyFailure(line)
}

function firstLines(text, count) {
	return text.split(/\r?\n/).slice(0, count).join("\n")
}

/** A `cc -g` build: compiler output passes through, a failure throws. */
function mustBuild(args) {
	const result = spawnSync(CC, args, { stdio: "inherit" })
	if (result.error || result.status !== 0) {
		throw new VerifyFailure(`build failed: ${CC} ${args.join(" ")}`)
	}
}

const HELLO_C = `#include <stdio.h>
int main(void) { printf("v-dap-hello\\n"); return 0; }
`
const CRASHER_C = `#include <signal.h>
static void crash(void) { raise(SIGSEGV); }
int main(void) { crash(); return 0; }
`
// The victim opts out of Yama scope 1 via PR_SET_PTRACER_ANY, so gdb may
// attach to it even though it is not gdb's child — stock Ubuntu confines
// ptrace to descendants otherwise. Windows has no prctl: Sleep instead.
const VICTIM_C = `#ifdef _WIN32
#include <windows.h>
int main(void) {
  for (;;) Sleep(1000);
  return 0;
}
#else
#include <sys/prctl.h>
#include <unistd.h>
#ifndef PR_SET_PTRACER_ANY
#define PR_SET_PTRACER_ANY ((unsigned long)-1)
#endif
int main(void) {
  prctl(PR_SET_PTRACER, PR_SET_PTRACER_ANY, 0, 0, 0);
  for (;;) pause();
  return 0;
}
#endif
`

function main() {
	// Preflight: gdb must be DAP-capable (Python + dap interpreter).
	if (!commandExists(GDB)) {
		console.log("gdb not found on PATH")
		process.exit(1)
	}
	if (!commandExists(CC)) {
		console.log(`no C compiler (${CC}) to build DAP fixtures`)
		process.exit(1)
	}
	const pythonOut = gdbOutput(["--batch", "-ex", 'python print("ok")'])
	const dapOut = gdbOutput(["-i=dap", "--batch"])
	if (pythonOut.includes("Python scripting is not supported")) {
		console.log(noDapSupport())
		process.exit(1)
	}
	if (/unrecognized|Could not find interpreter/i.test(dapOut)) {
		console.log(noDapSupport())
		process.exit(1)
	}
	console.log("Preflight passed: gdb is DAP-capable.")

	const work = fs.mkdtempSync(path.join(os.tmpdir(), "v-dap-verify-"))
	let victim = null
	let exitCode = 0
	try {
		// Fixtures: a hello-world for launch and a crasher for the core file.
		const helloC = path.join(work, "hello.c")
		const crasherC = path.join(work, "crasher.c")
		const helloBin = path.join(work, `hello${EXE}`)
		const crasherBin = path.join(work, `crasher${EXE}`)
		fs.writeFileSync(helloC, HELLO_C)
		fs.writeFileSync(crasherC, CRASHER_C)
		try {
			mustBuild(["-g", "-o", helloBin, helloC])
			mustBuild(["-g", "-o", crasherBin, crasherC])
		} catch (error) {
			console.log(`FAIL: fixture build: ${error.message}`)
			throw error
		}

		// Printers load check outside DAP: sourcing must not error.
		const printers = path.join(ROOT, "scripts", "gdb", "v_printers.py")
		let printersOut = ""
		let printersStatus = 1
		try {
			const printersResult = spawnSync(
				GDB,
				["--batch", "-ex", `source ${printers}`, "-ex", "quit"],
				{
					encoding: "utf8",
					stdio: ["ignore", "pipe", "pipe"],
				},
			)
			printersOut = `${printersResult.stdout ?? ""}\n${printersResult.stderr ?? ""}`
			printersStatus = printersResult.status ?? 1
		} catch {
			printersStatus = 1
		}
		if (printersStatus !== 0) {
			console.log("FAIL: pretty printers: source failed:")
			console.log(firstLines(printersOut, 20))
			throw new VerifyFailure("printers source failed")
		}
		if (/Traceback|Error in sourced command/i.test(printersOut)) {
			console.log("FAIL: pretty printers: source errors:")
			console.log(firstLines(printersOut, 20))
			throw new VerifyFailure("printers source errors")
		}
		console.log("PASS: pretty printers (batch source)")

		// Core file via gdb itself: deterministic, no core_pattern dependency.
		const corePath = path.join(work, "core.test")
		gdbOutput(
			[
				"--batch",
				"-ex",
				"run",
				"-ex",
				`generate-core-file ${corePath}`,
				"-ex",
				"kill",
				crasherBin,
			],
			{ cwd: work },
		)
		if (!fs.existsSync(corePath)) {
			failLine(`FAIL: core-file attach: gdb did not generate ${corePath}`)
		}

		// Live target for PID attach (what the provider's pid mapping feeds).
		const victimC = path.join(work, "victim.c")
		const victimBin = path.join(work, `victim${EXE}`)
		fs.writeFileSync(victimC, VICTIM_C)
		try {
			mustBuild(["-g", "-o", victimBin, victimC])
		} catch (error) {
			console.log(`FAIL: fixture build: ${error.message}`)
			throw error
		}
		victim = spawn(victimBin, [], { stdio: "ignore" })
		victim.on("error", () => {})
		if (victim.pid === undefined) {
			failLine("FAIL: live attach: could not spawn the victim process")
		}

		// The client bounds every request internally; the spawn timeout caps
		// the whole step so a wedged adapter fails loudly instead of hanging CI.
		const client = spawnSync(
			process.execPath,
			[
				path.join(ROOT, "scripts", "verify-dap-client.mjs"),
				`--gdb=${GDB}`,
				`--printers=${printers}`,
				`--work=${work}`,
				`--attach-bin=${victimBin}`,
				`--attach-pid=${victim.pid}`,
			],
			{ stdio: "inherit", timeout: 300_000 },
		)
		if (client.error || client.status !== 0) {
			exitCode = typeof client.status === "number" && client.status !== 0 ? client.status : 1
			return
		}
	} catch (error) {
		if (!(error instanceof VerifyFailure)) {
			throw error
		}
		exitCode = 1
	} finally {
		if (victim) {
			try {
				victim.kill("SIGKILL")
			} catch {
				// Already gone; the work-dir removal below is what matters.
			}
		}
		fs.rmSync(work, { recursive: true, force: true })
	}
	if (exitCode !== 0) {
		process.exit(exitCode)
	}
	console.log("PASS: verify-dap")
}

main()
